0,"Write a function in Python that initializes a stack data structure with a given capacity and performs operations to push, pop, and display the elements on the stack. Ensure proper error handling for cases like attempting to pop from an empty stack or exceeding the stack's capacity.",377,,"['```python
class Stack:
    def __init__(self, capacity):
        self.capacity = capacity
        self.stack = []

    def push(self, item):
        if len(self.stack) >= self.capacity:
            raise ValueError(""Stack overflow"")
        self.stack.append(item)

    def pop(self):
        if not self.stack:
            raise IndexError(""Pop from empty stack"")
        return self.stack.pop()

    def display(self):
        print(""Current stack:"", self.stack)

# Example usage
if __name__ == ""__main__"":
    stack = Stack(3)
    stack.push(10)
    stack.push(20)
    stack.display()  # Output: Current stack: [10, 20]

    try:
        stack.push(30)  # This should work
        stack.push(40)  # This will raise an exception
    except ValueError as e:
        print(e)

    stack.pop()
    stack.display()  # Output: Current stack: [10]

    try:
        stack.pop()  # This should work
        stack.pop()  # This will raise an exception
    except IndexError as e:
        print(e)
```']",13,[0],[],True,0,0,0,

