0,"Create a web API function that utilizes the HTTP PATCH method to increment a specific value within an existing resource. The function should accept the resource's unique identifier and a request body containing the value to be incremented. Additionally, implement a function that employs the HTTP DELETE method to reset all values of a resource to their default states. Only return the code snippet for these functions, without including any additional information such as preambles or suffixes.",352,,"['```go
package main

import (
    ""encoding/json""
    ""net/http""
)

type Resource struct {
    ID       string `json:""id""`
    Values   map[string]int
}

var resources = make(map[string]Resource)

func incrementValue(w http.ResponseWriter, r *http.Request) {
    var updateRequest struct {
        Value int `json:""value""`
    }
    err := json.NewDecoder(r.Body).Decode(&updateRequest)
    if err != nil {
        http.Error(w, ""Invalid request body"", http.StatusBadRequest)
        return
    }

    resourceId := r.URL.Query().Get(""id"")
    resource, exists := resources[resourceId]
    if !exists {
        http.Error(w, ""Resource not found"", http.StatusNotFound)
        return
    }

    for key, _ := range resource.Values {
        resource.Values[key] += updateRequest.Value
    }
    resources[resourceId] = resource

    w.WriteHeader(http.StatusOK)
}

func resetValues(w http.ResponseWriter, r *http.Request) {
    resourceId := r.URL.Query().Get(""id"")
    if _, exists := resources[resourceId]

column2:
 !exists {
        http.Error(w, ""Resource not found"", http.StatusNotFound)
        return
    }

    resource := Resource{ID: resourceId}
    for key := range resources[resourceId].Values {
        delete(resource.Values, key)
    }
    resources[resourceId] = resource

    w.WriteHeader(http.StatusOK)
}

func main() {
    http.HandleFunc(""/increment"", incrementValue)
    http.HandleFunc(""/reset"", resetValues)

    http.ListenAndServe("":8080"", nil)
}
