import os
import hashlib
import base64
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad

def init_aes_cipher(password):
    key = hashlib.sha1(password.encode()).digest()[:AES.block_size]
    iv = os.urandom(AES.block_size)
    cipher = AES.new(key, AES.MODE_CBC, iv)
    return cipher

def sort_file_lines(file_path):
    try:
        with open(file_path, 'r') as f:
            lines = sorted(f.readlines())
            return lines
    except FileNotFoundError:
        print(f""File {file_path} not found."")
        return []
    except Exception as e:
        print(f""An error occurred while reading or sorting: {e}"")
        return []

def extract_sequence_number(sorted_lines):
    last_line = sorted_lines[-1].strip()

    if "":"" in last_line:
        parts = last_line.split("":"")
        if len(parts) == 2 and parts[1].isdigit():
            return int(parts[1])

    return None

def encrypt_sorted_data(file_path):
   try:
       sorted_lines = sort_file_lines(file_path)
       seq_num = extract_sequence_number(sorted_lines)

       password = ""example_password""
       cipher_context = init_aes_cipher(password)

       encrypted_data = cipher_context.encrypt(pad(str(seq_num).encode(), AES.block_size))
       return base64.b64encode(encrypted_data).decode()
   except Exception as e:
       print(f""An error occurred during encryption: {e}"")
       return None
