def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def largest_prime(numbers):
    primes = [num for num in numbers if is_prime(num)]
    return max(primes) if primes else None
