import os
from typing import List, Dict

class FileParser:
    def __init__(self, file_types: List[str]):
        self.file_types = file_types

    def parse_file(self, file_path: str) -> str:
        if not any(file_path.endswith(ext) for ext in self.file_types):
            raise ValueError(f""Unsupported file type: {file_path}"")

        with open(file_path, 'r') as file:
            content = file.read()

        # Simulate grammar parsing and transformation
        parsed_content = f""Parsed content of {file_path}""
        return parsed_content

class LLVMIRGenerator:
    def generate_ir(self, parsed_code: str) -> str:
        # Simplified IR generation logic
        ir_code = f""LLVM IR code for:\n{parsed_code}""
        return ir_code

class ErrorHandler:
    @staticmethod
    def handle_error(error: Exception):
        print(f""Error: {error}"")

class Logger:
    @staticmethod
    def log(message: str):
        print(f""Log: {message}"")

def process_files(file_paths: List[str], file_parser: FileParser, ir_generator: LLVMIRGenerator) -> List[str]:
    ir_codes = []
    for file_path in file_paths:
        try:
            parsed_code = file_parser.parse_file(file_path)
            ir_code = ir_generator.generate_ir(parsed_code)
            ir_codes.append(ir_code)
        except Exception as e:
            ErrorHandler.handle_error(e)
            Logger.log(f""Failed to process {file_path}"")

    return ir_codes

# Example usage
file_paths = ['example.cpp', 'example.java', 'example.json', 'example.yaml']
file_parser = FileParser(['.cpp', '.java'])
ir_generator = LLVMIRGenerator()

