import requests
import json
from flask import Flask, request, Response

app = Flask(__name__)

def validate_api_key(api_key):
    # Add logic to validate the API key against a database or external service
    return True  # Placeholder for validation success

def fetch_resource(api_key, user_id, resource_name):
    # Make HTTP GET request to external data service
    url = f""https://data-service.example.com/api/{resource_name}?user_id={user_id}""

    headers = {
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json'
    }

    try:
        response = requests.get(url, headers=headers)

        if response.status_code == 200:
            return response.json()
        elif response.status_code == 401:
            raise Exception(""Invalid API key"")
        elif response.status_code == 404:
            raise Exception(""Resource not found"")
        else:
            raise Exception(f""Error occurred: {response.text}"")

    except requests.exceptions.RequestException as e:
        return {""error"": str(e)}

@app.route('/resource', methods=['GET'])
def get_resource():
    api_key = request.args.get('api_key')
    user_id = request.args.get('user_id')
    resource_name = request.args.get('resource_name')

    if not api_key or not user_id or not resource_name:
        return Response(status=400, mimetype='application/json'), ""Missing required parameters""

    if not validate_api_key(api_key):
        return Response(status=401, mimetype='application/json'), ""Invalid API key""

    try:
        data = fetch_resource(api_key, user_id, resource_name)

        if isinstance(data, dict) and 'error' in data.keys():
            return Response(status=data['error'].get('status', 500), mimetype='application/json'), data['error']['message']

        return Response(json.dumps(data), status=200, mimetype='application/json')

    except Exception as e:
        error_response = {""error"": str(e)}

        return Response(json.dumps(error_response), status=500, mimetype='application/json')

if __name__ == '__main__':
   app.run(debug=True)
