            return False
        return True

    def check_required_tags(element, required_tags):
        for tag in required_tags:
            found = False
            for subelem in element:
                if check_tag(subelem, tag):
                    found = True
                    break
            if not found:
                return False
        return True

    def check_nesting(element, parent_tag):
        if element.tag != parent_tag:
            return False
        for subelem in element:
            if not check_nesting(subelem, parent_tag):
                return False
        return True

    def check_attributes(element, attribute_name, expected_value=None):
        if attribute_name in element.attrib:
            if expected_value is None or element.attrib[attribute_name] == expected_value:
                return True
        return False

    def check_optional_tags(element, optional_tag):
        for subelem in element:
            if check_tag(subelem, optional_tag):
                continue
            else:
                return True
        return False

    required_tags = ['required1', 'required2']
    nesting = 'parentTag'
    attributes = {'attributeName': 'expectedValue'}
    optional_tag = 'optionalTag'

    if check_required_tags(root, required_tags) and \
       check_nesting(root, nesting) and \
       all(check_attributes(elem, **attributes) for elem in root.iter() if check_tag(elem, nesting)) and \
       check_optional_tags(root, optional_tag):
        return True
    else:
        return False

