invalid_xml_missing_required_tag = """"""<parentTag attributeName=""expectedValue""></parentTag>""""""

invalid_xml_nesting_error = """"""<parentTag><childTag></parentTag></childTag>""""""

invalid_xml_attribute_error = """"""<parentTag attributeName=""wrongValue""></parentTag>""""""

print(validate_xml(valid_xml))  # True
print(validate_xml(invalid_xml_missing_required_tag))  # False
print(validate_xml(invalid_xml_nesting_error))  # False
print(validate_xml(invalid_xml_attribute_error))  # False
