0,"Design and implement a function that takes a list of strings representing DNA sequences and returns the GC content percentage for each sequence. The GC content is the percentage of nucleotides in a DNA sequence that are either guanine (G) or cytosine (C). Ensure to handle invalid or empty sequences by returning an error message. Integrate this function into another function that accepts a file path as input, reads DNA sequences from the file, processes them using the GC content calculation function, and outputs the results to a new file along with any error messages encountered during processing.",347,,"['```python
def calculate_gc_content(dna_sequence):
    if not dna_sequence:
        return ""Error: Sequence is empty.""

    gc_count = sum(1 for nucleotide in dna_sequence.upper() if nucleotide in 'GC')
    total_nucleotides = len(dna_sequence)

    if total_nucleotides == 0:
        return ""Error: No valid nucleotides found.""

    gc_content_percentage = (gc_count / total_nucleotides) * 100
    return f""GC Content: {gc_content_percentage:.2f}%""

def process_dna_file(input_path, output_path):
    try:
        with open(input_path, 'r') as file:
            dna_sequences = file.read().splitlines()

        results = []
        for sequence in dna_sequences:
            result = calculate_gc_content(sequence)
            results.append(result)

        with open(output_path, 'w') as file:
            for line in results:
                file.write(line + '\n')

    except FileNotFoundError:
        results.append(""Error: Input file not found."")

    except Exception as e:
        results.append(f""Error: {str(e)}"")

    return '\n'.join(results)

# Example usage
