```python
import hashlib
import os
from tqdm import tqdm

def enhanced_file_md5_hash(file_path, chunk_size=65536, progress_bar=True):
    if ',' in file_path:
        paths = [path.strip() for path in file_path.split(',')]
    else:
        paths = [file_path]

    results = {}

    def hash_file(path):
        hasher = hashlib.md5()

        if progress_bar:
            total_bytes = os.path.getsize(path)
            with open(path, ""rb"") as f:
                for chunk in tqdm(iter(lambda: f.read(chunk_size), b""""), total=total_bytes, unit=""B"", unit_scale=True):
                    hasher.update(chunk)
        else:
            with open(path, ""rb"") as f:
                for chunk in iter(lambda: f.read(chunk_size), b""""):
                    hasher.update(chunk)

        return path, hasher.hexdigest()

    for path in paths:
        results[path], _ = hash_file(path)

    return results
```

