def transfer_file_via_ftp(local_file_path, remote_file_path, ftp_host, ftp_user, ftp_password):
    try:
        with FTP(ftp_host) as ftp:
            ftp.login(user=ftp_user, passwd=ftp_password)
            with open(local_file_path, 'rb') as file:
                ftp.storbinary(f'STOR {remote_file_path}', file)
    except Exception as e:
        print(f""Error during FTP transfer: {e}"")

def process_csv(input_csv, output_file, delimiter, validation_rules):
    try:
        with open(input_csv, 'r') as csvfile:
            for line in csvfile:
                row = line.strip().split(delimiter)
                if validate_row(row, validation_rules):
                    local_file_path = os.path.join(os.getcwd(), row[0])
                    remote_file_path = row[1]
                    transfer_file_via_ftp(local_file_path, remote_file_path, 'ftp.example.com', 'user', 'password')
                    md5_hash = calculate_md5(local_file_path)
                    print(f""File {local_file_path} transferred and MD5: {md5_hash}"")
                else:
                    print(""Row validation failed:"", row)
    except Exception as e:
        print(f""Error processing CSV file: {e}"")

if __name__ == ""__main__"":
    if len(sys.argv) != 5:
        print(""Usage: python script.py input_csv output_file delimiter validation_rules"")
    else:
        input_csv = sys.argv[1]
        output_file = sys.argv[2]
        delimiter = sys.argv[3]
        validation_rules = sys.argv[4].split(',')
