0,"Design a Python script that integrates WebSocket connection and JSON message processing for real-time data exchange. The script should take three command-line arguments: WebSocket server URL, output file name, and message topic filter. Connect to the WebSocket server using the websocket-client library, subscribe to specified topics, and parse incoming JSON messages. Store received data in the output file, categorize by topic, and include timestamp for each message. Implement error handling to ensure smooth operation during WebSocket connections and data processing.",120,,"['```python
import websocket
import json
import sys
from datetime import datetime

def on_message(ws, message):
    try:
        data = json.loads(message)
        with open(sys.argv[2], 'a') as file:
            file.write(f""{datetime.now()}: Topic: {data['topic']}, Data: {json.dumps(data['payload'])}\n"")
    except Exception as e:
        print(f""Error processing message: {e}"")

def on_error(ws, error):
    print(f""Error: {error}"")

def on_close(ws):
    print(""### closed ###"")

def on_open(ws):
    topics = sys.argv[3].split(',')
    for topic in topics:
        ws.send(json.dumps({""action"": ""subscribe"", ""topic"": topic}))

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: python script.py <WebSocket server URL> <output file name> <message topic filter>"")
        sys.exit(1)

    websocket.enableTrace(True)
    ws = websocket.WebSocketApp(f""{sys.argv[1]}/ws"",
                                on_message=on_message,
                                on_error=on_error,
                                on_close=on_close)
    ws.on_open = on_open

    try:
        ws.run_forever()
    except KeyboardInterrupt:
        print(""Exiting..."")
