0,"Design and implement a function that processes an input array of stock prices, calculates the moving average for a specified window size, and returns an array containing the calculated moving averages at each point in time. Ensure that the function handles edge cases, such as when the window size exceeds the length of the input array or when there are not enough consecutive elements to calculate a moving average.",770,,"['```python
def moving_average(prices, window_size):
    if window_size <= 0:
        raise ValueError(""Window size must be greater than zero"")

    if len(prices) < window_size:
        raise ValueError(""Not enough data points for the specified window size"")

    moving_averages = []
    for i in range(len(prices) - window_size + 1):
        window_sum = sum(prices[i:i+window_size])
        moving_average = window_sum / window_size
        moving_averages.append(moving_average)

    return moving_averages
