LOCAL_CACHE_FILE_DIR = os.path.join(SYSTEM_CACHE_DIR, ""cache_files"")

# Ensure directories exist
os.makedirs(TEMP_DOWNLOAD_DIR, exist_ok=True)
os.makedirs(LOCAL_CACHE_FILE_DIR, exist_ok=True)

def check_font_cache(font_name):
    return os.path.exists(os.path.join(LOCAL_CACHE_FILE_DIR, f""{font_name}.ttf""))

def download_font_file(font_url, temp_path):
    response = requests.get(font_url)
