import random

class EnhancedRandomGenerator:
    def __init__(self, seed=None):
        self.generator = random.Random(seed)

    def generate_float(self, low=0.0, high=1.0):
        return self.generator.uniform(low, high)

    def generate_int(self, low=0, high=100):
        return self.generator.randint(low, high)

    def ToString(self):
        return f""EnhancedRandomGenerator with seed: {self.generator.random()}""

