1,"Design and implement a Python function that creates a RESTful API endpoint for handling file uploads. The function should accept an HTTP POST request with a multipart/form-data content type, extract the uploaded file, and save it to a specified directory on the server. The function should also return a JSON response indicating the success or failure of the upload operation, including an error message if applicable. Additionally, ensure proper error handling for cases such as invalid file types or server storage issues.",312,,"[""```python
from flask import Flask, request, jsonify
import os

app = Flask(__name__)

UPLOAD_FOLDER = '/path/to/the/uploads'
ALLOWED_EXTENSIONS = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400
    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400
    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        filepath = os.path.join(UPLOAD_FOLDER, filename)
        try:
            file.save(filepath)
            return jsonify({'message': 'File successfully uploaded'}), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500
    else:
        return jsonify({'error': 'Invalid file type'}), 400

if __name__ == '__main__':
    app.run(debug=True)
