import re

def validate_user_setup(user_setup):
    if not user_setup.get('email'):
        return ""Error: Email address is required""

    profile = user_setup.get('profile')
    if not profile or not profile.name:
        return ""Error: User name is required""

    notification_handler = user_setup.get('notification_handler')
    if not callable(notification_handler):
        return ""Error: A valid notification handler function is required""

    email = user_setup['email']
    if not re.match(r""[^@]+@[^@]+\.[^@]+"", email):
        return ""Error: Invalid email format""

    predefined_roles = ['admin', 'user']
    if profile.role not in predefined_roles:
        return f""Error: Invalid role '{profile.role}'. Must be one of {predefined_roles}""

    if profile.age < 18:
        return ""Error: User must be at least 18 years old""

    try:
        # Additional checks can be added here
        pass
    except Exception as e:
        return f""Error: An unexpected error occurred - {str(e)}""

    return ""Success: User setup validated""

class UserProfile:
