{
  ""code"": ""// Import necessary libraries\nimport json\nfrom datetime import datetime\nimport asyncio\nfrom typing import List, Dict, Optional\n\n# Define a function to fetch user details from the external database\nclass UserDatabase:\n    async def get_user_details(self, user_id: str) -> Dict[str, Any]:\n        # Simulate an asynchronous database call\n        await asyncio.sleep(1)\n        return {\n            'user_id': user_id,\n            'birth_year': 1990,  # Example birth year for demonstration purposes\n        }\n\n# Define the main function to process user profiles\ndef process_user_profiles(user_profiles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:\n    db = UserDatabase()\n    updated_profiles = []\n\n    async def fetch_and_update_profile(profile: Dict[str, Any]) -> None:\n        user_id = profile['user_id']\n        try:\n            details = await db.get_user_details(user_id)\n            birth_year = details.get('birth_year')\n            if not birth_year:\n                raise ValueError('Birth year missing or invalid for user_id: {}'.format(user_id))\n\n            current_year = datetime.now().year\n            age = current_year - birth_year\n            profile['age'] = age\n            profile.append(birth_year)\n            updated_profiles.append(profile)\n        except Exception as e:\n            print('Error processing user_id {}: {}'.format(user_id, str(e)))\n\n    # Asynchronously fetch and update each profile\n    tasks = [fetch_and_update_profile(profile) for profile in user_profiles]\n    await asyncio.gather(*tasks)\n\n    # Filter out profiles with age below 18 or missing required fields\n    filtered_profiles = [\n        profile for profile in updated_profiles\n        if profile.get('age', 0) >= 18 and 'name' in profile and 'email' in profile\n    ]\n\n    # Sort profiles by age in ascending order\n    sorted_profiles = sorted(filtered_profiles, key=lambda x: x['age'])\n\n    return sorted_profiles\n\n# Example usage of the process_user_profiles function\nif __name__ == '__main__':\n    user_profiles = [\n        {'user_id': '1', 'name': 'John Doe', 'email': 'john@example.com'},\n        {'user_id': '2', 'name': 'Jane Smith', 'email': 'jane@example.com'},\n    ]\n\n    result = asyncio.run(process_user_profiles(user_profiles))\n    print(json.dumps(result, indent=4))\n""
}
