2,"Write a Python script that analyzes input from a CSV file and outputs a summary report. The script should accept command line arguments for specifying the input CSV file, output directory, and delimiter used in the CSV. If no input file is provided, the script should display usage instructions. It should read the CSV file line by line, count the number of rows and columns, and generate a summary report containing this information along with any unique values found in specific columns. The script should use standard libraries for file handling and data processing.",121,,"['```python
import csv
import os
import sys

def main():
    if len(sys.argv) < 2:
        print(""Usage: python summary_report.py <input_file> [-o output_directory] [-d delimiter]"")
        sys.exit(1)

    input_file = sys.argv[1]
    output_directory = 'output'
    delimiter = ','

    for arg in sys.argv[2:]:
        if arg.startswith('-o'):
            output_directory = arg.split('=')[1]
        elif arg.startswith('-d'):
            delimiter = arg.split('=')[1]

    if not os.path.isfile(input_file):
        print(f""Error: Input file '{input_file}' does not exist."")
        sys.exit(1)

    row_count = 0
    column_count = None
    unique_values = {}

    with open(input_file, newline='') as csvfile:
        reader = csv.reader(csvfile, delimiter=delimiter)
        for row in reader:
            if row_count == 0:
                column_count = len(row)
                unique_values = {i: set() for i in range(column_count)}
            for i, value in enumerate(row):
                unique_values[i].add(value)
            row_count += 1

    summary_file = os.path.join(output_directory, 'summary_report.txt')
    with open(summary_file, 'w') as report:
        report.write(f""File: {input_file}\n"")
        report.write(f""Rows: {row_count}\n"")
        report.write(f""Columns: {column_count}\n"")
        report.write(""\nUnique Values:\n"")
        for col_index, values in unique_values.items():
            report.write(f""Column {col_index}: {len(values)} unique values\n"")

if __name__ == ""__main__"":
    main()
