import hashlib
import os
import threading

def calculate_md5(file_path, chunk_size=8192):
    hash_md5 = hashlib.md5()
    chunk_size = 8192

    if not os.path.exists(file_path):
        return None, ""File not found""

    if not os.path.isfile(file_path):
        return None, ""Not a file""

    def process_chunk(chunk, hash_obj):
        hash_obj.update(chunk)

    def process_file():
        with open(file_path, 'rb') as file:
            while True:
                chunk = file.read(chunk_size)
                if not chunk:
                    break
                process_chunk(chunk, hash_md5)

    thread = threading.Thread(target=process_file)
    thread.start()
    thread.join()

    return hash_md5.hexdigest(), None

def check_file_integrity(original_hash, new_hash):
    if original_hash == new_hash:
        return True
    else:
        return False

def compare_files(file_path_1, file_path_2):
    original_hash_1, error_1 = calculate_md5(file_path_1)
    original_hash_2, error_2 = calculate_md5(file_path_2)

    if error_1 or error_2:
        print(""Error:"", error_1 or error_2)
        return False

    result = check_file_integrity(original_hash_1, original_hash_2)

    if result:
        print(""Files are identical."")
    else:
        print(""Files are different."")

