import multiprocessing as mp
import numpy as np

class ParallelBinarySearch:
    def _validate_input(self, arr):
        if not isinstance(arr, (list, np.ndarray)):
            raise ValueError(""Input must be a list or numpy array."")
        if not all(isinstance(x, (int, float)) for x in arr):
            raise ValueError(""All elements in the input list must be integers or floats."")

    def parallel_binary_search(self, arr):
        self._validate_input(arr)
        num_processes = mp.cpu_count()
        chunk_size = len(arr) // num_processes

        # Initialize shared memory for results
        result_queue = mp.Queue()

        # Function to perform binary search on a chunk of the array
        def search_chunk(start, end):
            chunk = arr[start:end]
            sorted_chunk = np.sort(chunk)
            for target in chunk:
                left, right = 0, len(sorted_chunk) - 1
                while left <= right:
                    mid = (left + right) // 2
                    if sorted_chunk[mid] == target:
                        result_queue.put(True)
                        return True
                    elif sorted_chunk[mid] < target:
                        left = mid + 1
                    else:
                        right = mid - 1
            result_queue.put(False)
            return False

        # Create and start processes for each chunk of the array
        processes = []
        for i in range(num_processes):
            start_index = i * chunk_size + (i < num_processes - 1)
            end_index = start_index + chunk_size
            process = mp.Process(target=search_chunk,
                                 args=(start_index, end_index))
            process.start()
            processes.append(process)

        # Wait for all processes to finish and collect results from the queue
        results_list = []
        for process in processes:
            process.join()
            while not result_queue.empty():
                results_list.append(result_queue.get())

        return all(results_list)
