import jwt
import time

# Simulated secret key for JWT encoding/decoding
SECRET_KEY = 'your_secret_key_here'

def create_session_token(user_id):
    payload = {
        'user_id': user_id,
        'exp': int(time.time()) + 3600  # Token expires in 1 hour
    }
    token = jwt.encode(payload, SECRET_KEY, algorithm='HS256')
    return token

def fetch_apn_registration_id(token):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
        user_id = payload['user_id']
        # Simulate fetching APN registration ID logic here
        apn_id = f""APN_{user_id}_registration_ID""
        return True, apn_id
    except jwt.ExpiredSignatureError:
        return False, ""Token expired""
    except jwt.InvalidTokenError:
        return False, ""Invalid token""

def main():
    sessions = []
    num_sessions = 5

    for i in range(num_sessions):
        user_id = f""user_{i+1}""
        session_token = create_session_token(user_id)
        sessions.append({'session_id': i+1, 'token': session_token})

        success, apn_id = fetch_apn_registration_id(session_token)
        if success:
            print(f""Session {sessions[i]['session_id']}: Token '{sessions[i]['token']}' retrieved APN ID: {apn_id}"")
        else:
            print(f""Session {sessions[i]['session_id']}: Failed to retrieve APN ID. Error: {apn_id}"")

if __name__ == ""__main__"":
