import random

class Product:
    def __init__(self, code, category):
        self.code = code
        self.category = category

def generate_product_list(num_products):
    if num_products < 1:
        raise ValueError(""Invalid product count input. Must be greater than or equal to 1."")

    products = set()
    categories = [""Electronics"", ""Clothing"", ""Books"", ""Furniture"", ""Toys""]

    while len(products) < num_products:
        category = random.choice(categories)
        product_code = random.randint(1, 5000)
        category_product_code = f""{category}_{product_code}""

        if category_product_code not in products:
            products.add(category_product_code)

    return [Product(code, category_product_code.split(""_"")[0]) for code in products]

try:
    num_products = int(input(""Enter the number of products to generate: ""))
    product_list = generate_product_list(num_products)
    for product in product_list:
        print(f""Product Code: {product.code}, Category: {product.category}"")
except Exception as e:
    print(f""An error occurred: {e}"")
