    required_params = ['api_key', 'user_id', 'resource_name']
    if not all(param in request.args for param in required_params):
        return jsonify({'error': 'Missing parameters'}), 400

    api_key = request.args['api_key']
    user_id = request.args['user_id']
    resource_name = request.args['resource_name']

    if not validate_api_key(api_key):
        return jsonify({'error': 'Invalid API key'}), 401

    headers = {'Authorization': f'Bearer {api_key}'}
    response = requests.get(f'https://external-service.com/{resource_name}', headers=headers)

    if response.status_code == 200:
        return jsonify(response.json())
    elif response.status_code == 401:
        return jsonify({'error': 'Invalid API key'}), 401
    elif response.status_code == 404:
        return jsonify({'error': 'Resource not found'}), 404
    else:
