def enhanced_file_md5_hash(file_paths, chunk_size=64*1024, parallel=False):
    hashes = {}
    if not isinstance(file_paths, list):
        file_paths = [file_paths]

    def hash_file(file_path):
        hash_obj = hashlib.md5()
        with open(file_path, 'rb') as f:
            while chunk := f.read(chunk_size):
                hash_obj.update(chunk)
        return file_path, hash_obj.hexdigest()

    if parallel and threading.active_count() > 1:
        results = [threading.Thread(target=lambda fp: hashes.update(hash_file(fp)), args=(fp,)).start() for fp in file_paths]
        for thread in results:
            thread.join()
    else:
        for fp in file_paths:
            hash_value = hash_file(fp)
            hashes[hash_value[0]] = hash_value[1]

    return hashes

