func (v *Version) Parse(versionStr string) error {
	re := regexp.MustCompile(`^(\d+)([^\d]+)(\d+)([^\d]+)?(\d+)?$`)
	matches := re.FindStringSubmatch(versionStr)
	if len(matches) != 6 {
		return fmt.Errorf(""invalid version format"")
	}
	var err error
	v.Major, err = strconv.Atoi(matches[1])
	if err != nil {
		return err
	}
	v.Minor, err = strconv.Atoi(matches[3])
	if err != nil {
		return err
	}
	v.Patch, err = strconv.Atoi(matches[5])
	if err != nil {
		return err
	}
	v.VersionStr = versionStr
	return nil
}

func (v *Version) String() string {
	return fmt.Sprintf(""%d%s%d%s%d"", v.Major, v.Delimiter, v.Minor, v.Delimiter, v.Patch)
}

func main() {
	version, err := NewVersion(""1.2.3"", ""."", true, ""abc"", 50)
	if err != nil {
		fmt.Println(""Error:"", err)
		return
	}
	fmt.Println(""Updated Version:"", version.String())
}
