def transfer_file(ftp_client, local_file_path, remote_file_path):
    with open(local_file_path, 'rb') as file:
        md5_hash = compute_md5_hash(local_file_path)
        ftp_client.storbinary(f'STOR {remote_file_path}', file)
        computed_md5 = compute_md5_hash(remote_file_path)
        if md5_hash != computed_md5:
            raise ValueError('MD5 hash mismatch')


def compute_md5_hash(file_path):
    hasher = md5()
    with open(file_path, 'rb') as f:
        buf = f.read(65536)  # Read in chunks of 64KB
        while len(buf) > 0:
            hasher.update(buf)
            buf = f.read(65536)
    return hasher.hexdigest()


