import xml.etree.ElementTree as ET

def parse_xml_to_dict(file_path):
    tree = ET.parse(file_path)
    root = tree.getroot()

    def parse_element(element):
        result = {}
        if element.text:
            result['text'] = element.text.strip()
        for child in element:
            child_name = child.tag
            child_data = parse_element(child)
            if child_name in result:
                if type(result[child_name]) is list:
                    result[child_name].append(child_data)
                else:
                    result[child_name] = [result[child_name], child_data]
            else:
                result[child_name] = child_data
        return {element.tag: result}

    return parse_element(root)[root.tag]

# Example usage
file_path = 'example.xml'
xml_dict = parse_xml_to_dict(file_path)
print(xml_dict)
```

