0,"Design a function to calculate the GC content percentage for each DNA sequence in a list, handling invalid or empty sequences with error messages. Integrate this into another function that reads DNA sequences from a file, processes them using the GC content function, and outputs results to a new file, including any errors encountered.",347,,"['```python
def calculate_gc_content(dna_sequence):
    if not dna_sequence:
        return ""Error: Sequence is empty.""
    gc_count = sum(1 for base in dna_sequence.upper() if base in 'GC')
    return (gc_count / len(dna_sequence)) * 100

def process_dna_file(input_file, output_file):
    try:
        with open(input_file, 'r') as infile, open(output_file, 'w') as outfile:
            for line_number, line in enumerate(infile, start=1):
                dna_sequence = line.strip()
                gc_content = calculate_gc_content(dna_sequence)
                if isinstance(gc_content, str) and ""Error"" in gc_content:
                    outfile.write(f""Line {line_number}: {gc_content}\n"")
                else:
                    outfile.write(f""DNA Sequence {line_number}: GC Content = {gc_content:.2f}%\n"")
    except FileNotFoundError:
        print(""Error: Input file not found."")
    except Exception as e:
        print(f""An error occurred: {e}"")

# Example usage
process_dna_file('input.txt', 'output.txt')
