def enhanced_file_md5_hash(file_paths, chunk_size=65536, parallel=True):
    if not isinstance(file_paths, (list, tuple)):
        file_paths = [file_paths]

    def _calculate_md5_chunk(file_path):
        with open(file_path, 'rb') as f:
            data_chunks = iter(lambda: f.read(chunk_size), b'')
            return hashlib.md5(b''.join(data_chunks)).hexdigest()

    if parallel:
        with ThreadPoolExecutor() as executor:
            hash_results = executor.map(_calculate_md5_chunk, file_paths)
            return {file_path: hash_result for file_path, hash_result in zip(file_paths, hash_results)}

    hashes = {}
    for file_path in file_paths:
        with open(file_path, 'rb') as f:
            data_chunks = iter(lambda: f.read(chunk_size), b'')
            hashes[file_path] = hashlib.md5(b''.join(data_chunks)).hexdigest()

    return hashes

