0,"Create a Python script that processes a CSV file and generates a summary report. The script should accept command-line arguments for the input file, output directory, and column delimiter. If no input file is provided, display usage instructions. Sequentially read the CSV, count rows and columns, and compile a summary report including total rows, columns, and distinct values in specified columns. Use standard libraries for file handling and data manipulation.",121,,"['```python
import csv
import os
import sys

def main():
    if len(sys.argv) < 2:
        print(""Usage: python script.py <input_file> <output_directory> <delimiter>"")
        return

    input_file = sys.argv[1]
    output_dir = sys.argv[2]
    delimiter = sys.argv[3]

    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    summary_data = {
        'total_rows': 0,
        'total_columns': 0,
        'distinct_values': {}
    }

    try:
        with open(input_file, mode='r', newline='', encoding='utf-8') as file:
            reader = csv.reader(file, delimiter=delimiter)
            for row in reader:
                if summary_data['total_rows'] == 0:
                    summary_data['total_columns'] = len(row)
                summary_data['total_rows'] += 1
                for i, value in enumerate(row):
                    if i not in summary_data['distinct_values']:
                        summary_data['distinct_values'][i] = set()
                    summary_data['distinct_values'][i].add(value)

    except Exception as e:
        print(f""Error processing the file: {e}"")
        return

    output_file_path = os.path.join(output_dir, 'summary_report.txt')
    with open(output_file_path, mode='w', encoding='utf-8') as report_file:
        report_file.write(f""Total Rows: {summary_data['total_rows']}\n"")
        report_file.write(f""Total Columns: {summary_data['total_columns']}\n"")
        for column, values in summary_data['distinct_values'].items():
            report_file.write(f""Column {column} Distinct Values: {len(values)}\n"")

if __name__ == ""__main__"":
    main()
