import random

def generate_random_matrix(rows, columns):
    if not isinstance(rows, int) or not isinstance(columns, int):
        raise ValueError(""Both rows and columns must be integers."")
    if rows <= 0 or columns <= 0:
        raise ValueError(""Rows and columns must be positive integers."")

    return [[random.random() for _ in range(columns)] for _ in range(rows)]

def validate_matrix(matrix, expected_rows, expected_columns):
    if len(matrix) != expected_rows:
        return False
    for row in matrix:
        if len(row) != expected_columns or not all(0 <= elem <= 1 for elem in row):
            return False
    return True

# Example usage:
