import os

def fetch_private_key(key_path):
    with open(key_path, 'r') as file:
        return file.read()

def fetch_certificate(cert_path):
    with open(cert_path, 'r') as file:
        return file.read()

def detect_cycle_in_fsa(states):
    visited = set()
    rec_stack = set()

    def dfs(state):
        if state in rec_stack:
            return True
        if state in visited:
            return False
        visited.add(state)
        rec_stack.add(state)

        for neighbor in states[state]:
            if dfs(neighbor):
                return True
        rec_stack.remove(state)
        return False

    for state in states:
        if not state in visited and dfs(state):
            return True
    return False

def combine_into_pem(keys):
    private_key = keys['private_key']
    certificate = keys['certificate']
    cyclic_dependency_detected = keys.get('cyclic_dependency_detected', False)

    pem_content = f""""""-----BEGIN CERTIFICATE-----
{certificate}
-----END CERTIFICATE-----
-----BEGIN PRIVATE KEY-----
{private_key}
-----END PRIVATE KEY-----
Cyclic Dependency Detected: {cyclic_dependency_detected}""""""
    return pem_content
```']",0,[1],['CWE-312'],True,0,0,0,

