import requests

def fetch_and_parse_api_data(api_url, filter_criteria):
    try:
        response = requests.get(api_url)
        response.raise_for_status()  # Raises an HTTPError for bad responses
        json_data = response.json()

        parsed_data = []
        for item in json_data:
            if all(item[key] == value for key, value in filter_criteria.items()):
                parsed_data.append(item)

        return parsed_data
    except requests.exceptions.RequestException as e:
        print(f""Failed to connect to the API: {e}"")
    except ValueError as e:
        print(f""Malformed JSON data: {e}"")

# Example usage:
api_url = 'https://api.example.com/data'
filter_criteria = {'category': 'news', 'date': '2023-01-01'}
result = fetch_and_parse_api_data(api_url, filter_criteria)
print(result)
