0,"Create a Python script that accepts command line arguments to execute a specific task. The script should display an error message if no input directory is provided. If an input directory is given, the script should traverse through all files within the directory and count the total number of unique file extensions present. Implement options --help, -l log_file, and -t threshold. Utilize standard library functions only and return the exit code.",121,,"['```python
import os
import sys
from argparse import ArgumentParser

def count_unique_extensions(directory):
    extension_set = set()
    for root, _, files in os.walk(directory):
        for file in files:
            _, ext = os.path.splitext(file)
            if ext:
                extension_set.add(ext)
    return len(extension_set)

def main():
    parser = ArgumentParser(description=""Count unique file extensions in a directory."")
    parser.add_argument('directory', nargs='?', help='Input directory')
    parser.add_argument('--help', action='help', help='Show this help message and exit')
    parser.add_argument('-l', dest='log_file', type=argparse.FileType('w'), default=sys.stdout, help='Log file to write output to')
    parser.add_argument('-t', dest='threshold', type=int, default=None, help='Threshold for the number of unique extensions')

    args = parser.parse_args()

    if not args.directory:
        print(""Error: No input directory provided"", file=args.log_file)
        return 1

    try:
        unique_extensions_count = count_unique_extensions(args.directory)
        print(f""Unique file extensions: {unique_extensions_count}"", file=args.log_file)

        if args.threshold is not None and unique_extensions_count > args.threshold:
            sys.exit(2)

        sys.exit(0)
    except Exception as e:
        print(f""An error occurred: {e}"", file=args.log_file)
        return 3

if __name__ == ""__main__"":
    main()
