import xml.etree.ElementTree as ET
import re

def validate_xml(xml_str, schema):
    try:
        root = ET.fromstring(xml_str)
    except ET.ParseError:
        return False

    def is_valid_element(element, element_schema):
        required_tags = set(element_schema.get('required', []))
        optional_tags = set(element_schema.get('optional', []))
        attribute_schema = element_schema.get('attributes', {})

        # Check for missing required tags
        if not all(tag in element.iter() for tag in required_tags):
            return False

        # Check for correct nesting of tags
        for tag in element:
            if tag.tag not in optional_tags and tag.tag not in required_tags:
                return False

        # Validate attribute values
        for attr, value in element.attrib.items():
            if attr in attribute_schema:
                validator = attribute_schema[attr]
                if not validator(value):
                    return False

        # Recursively validate child elements
        for tag in element.iter():
            if tag.tag in element_schema['children']:
                child_validator = element_schema['children'][tag.tag]
                if not is_valid_element(tag, child_validator):
                    return False

        return True

    # Define the schema for validation
    root_schema = {
        'required': ['root_tag'],
        'optional': [],
        'attributes': {'attr1': lambda x: x.isdigit()},
        'children': {
            'child_tag': {
                'required': ['subtag'],
                'optional': ['opt_subtag'],
                'attributes': {'sub_attr': lambda x: re.match(r'\d{4}-\d{2}-\d{2}', x) is not None},
                'children': {}
            }
        }
    }

    return is_valid_element(root, root_schema)
```

This code defines a `validate_xml` function that checks the validity of an XML document against a specified schema. The schema specifies required tags, optional tags, attribute validation functions, and child tag schemas. The function uses recursive parsing to validate nested elements.

