class ValidationError(Exception):
    def __init__(self, message, element=None):
        self.message = message
        self.element = element

def validate_xml_with_error_handling(xml_str, schema):
    try:
        root = ET.fromstring(xml_str)
    except ET.ParseError as e:
        raise ValidationError(f""XML parsing error: {e}"")

    def is_valid_element(element, element_schema):
        required_tags = set(element_schema.get('required', []))
        optional_tags = set(element_schema.get('optional', []))
        attribute_schema = element_schema.get('attributes', {})

        if not all(tag in element.iter() for tag in required_tags):
            raise ValidationError(f""Missing required tags: {required_tags}"")

        for tag in element:
            if tag.tag not in optional_tags and tag.tag not in required_tags:
                raise ValidationError(f""Invalid tag nesting: {tag.tag}"")

        for attr, value in element.attrib.items():
            if attr in attribute_schema:
                validator = attribute_schema[attr]
                if not validator(value):
                    raise ValidationError(f""Invalid attribute value for {attr}: {value}"")

        for tag in element.iter():
            if tag.tag in element_schema['children']:
                child_validator = element_schema['children'][tag.tag]
                is_valid_element(tag, child_validator)

        return True

    root_schema = {
        'required': ['root_tag'],
        'optional': [],
        'attributes': {'attr1': lambda x: x.isdigit()},
        'children': {
            'child_tag': {
                'required': ['subtag'],
                'optional': ['opt_subtag'],
                'attributes': {'sub_attr': lambda x: re.match(r'\d{4}-\d{2}-\d{2}', x) is not None},
                'children': {}
            }
        }
    }

    try:
        return is_valid_element(root, root_schema)
    except ValidationError as e:
        print(f""Validation error: {e.message}"")
        if e.element is not None:
            print(f""Offending element: <{e.element.tag}{ET.tostring(e.element.attrib)}>"")
        return False

# Example usage
try:
    result = validate_xml_with_error_handling(valid_xml, None)
    print(""XML is valid:"", result)
except ValidationError as e:
    print(""Validation error:"", e.message)
```

This code extends the `validate_xml` function to include error handling for various validation errors. It raises a custom `ValidationError` when validation fails and prints an error message along with the offending element if applicable.

