def customize_validation_rules(schema, rules):
    for tag, rule in rules.items():
        if tag not in schema:
            schema[tag] = {}

        if 'required' in rule:
            schema[tag]['required'] = rule['required']

        if 'optional' in rule:
            schema[tag]['optional'] = rule['optional']

        if 'attributes' in rule:
            schema[tag]['attributes'] = rule['attributes']

        if 'children' in rule:
            schema[tag]['children'] = customize_validation_rules(schema.get(tag, {}).get('children', {}), rule['children'])

    return schema

