import csv

def validate_csv(file_path):
    required_columns = {'Name': str, 'Age': int, 'Gender': str, 'Income': float}
    valid_genders = {'Male', 'Female'}

    with open(file_path, mode='r') as file:
        reader = csv.DictReader(file)

        for row in reader:
            if not all(column in row for column in required_columns):
                return False

            try:
                age = int(row['Age'])
                income = float(row['Income'])

                if not isinstance(age, required_columns['Age']):
                    return False
                if not isinstance(income, required_columns['Income']):
                    return False

                if age < 0 or income <= 0:
                    return False

                gender = row['Gender']
                if gender not in valid_genders:
                    return False

            except (ValueError, TypeError):
                return False

    return True
